import pandas as pd
import numpy as np

# Load data
waste_df = pd.read_csv('chunks_csv/moran_local_2023_waste.csv')
adj_df = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Step 1: Handle missing data
waste_df.dropna(subset=['Waste_value'], inplace=True)
data_points_used = len(waste_df)
print(f'data_points_used = {data_points_used}')

# Step 2: Compute global statistics
mean_waste = waste_df['Waste_value'].mean()
std_waste = waste_df['Waste_value'].std()

# Step 3: Classify high/low
waste_df['is_high'] = waste_df['Waste_value'] > (mean_waste + std_waste)
waste_df['is_low'] = waste_df['Waste_value'] < (mean_waste - std_waste)

# Step 4: Build neighbor list
borough_neighbors = {}
for _, row in adj_df.iterrows():
    borough = row['borough']
    neighbor = row['neighbor']
    if borough not in borough_neighbors:
        borough_neighbors[borough] = set()
    borough_neighbors[borough].add(neighbor)

# Step 5: Compute neighbor average
borough_to_waste = dict(zip(waste_df['borough'], waste_df['Waste_value']))
waste_df['neighbor_avg'] = 0.0

for index, row in waste_df.iterrows():
    borough = row['borough']
    neighbors = borough_neighbors.get(borough, [])
    if not neighbors:
        waste_df.at[index, 'neighbor_avg'] = np.nan
    else:
        neighbor_wastes = []
        for neighbor in neighbors:
            if neighbor in borough_to_waste:
                neighbor_wastes.append(borough_to_waste[neighbor])
        if not neighbor_wastes:
            waste_df.at[index, 'neighbor_avg'] = np.nan
        else:
            waste_df.at[index, 'neighbor_avg'] = np.mean(neighbor_wastes)

# Step 6: Compute local statistic
waste_df['local_stat'] = (waste_df['Waste_value'] - mean_waste) * (waste_df['neighbor_avg'] - mean_waste)

# Step 7: Permutation test
num_permutations = 500
permuted_local_stats = []

boroughs = waste_df['borough'].tolist()
original_wastes = waste_df['Waste_value'].tolist()

for _ in range(num_permutations):
    shuffled_wastes = np.random.permutation(original_wastes)
    shuffled_borough_to_waste = {borough: shuffled_wastes[i] for i, borough in enumerate(boroughs)}
    permuted_neighbor_avgs = []
    for index, row in waste_df.iterrows():
        borough = row['borough']
        neighbors = borough_neighbors.get(borough, [])
        if not neighbors:
            permuted_neighbor_avgs.append(np.nan)
        else:
            neighbor_wastes = []
            for neighbor in neighbors:
                if neighbor in shuffled_borough_to_waste:
                    neighbor_wastes.append(shuffled_borough_to_waste[neighbor])
            if not neighbor_wastes:
                permuted_neighbor_avgs.append(np.nan)
            else:
                permuted_neighbor_avgs.append(np.mean(neighbor_wastes))
    permuted_local_stat = []
    for i in range(len(boroughs)):
        waste_val = shuffled_wastes[i]
        avg_neighbor = permuted_neighbor_avgs[i]
        if np.isnan(avg_neighbor):
            permuted_local_stat.append(np.nan)
        else:
            permuted_local_stat.append((waste_val - mean_waste) * (avg_neighbor - mean_waste))
    permuted_local_stats.append(permuted_local_stat)

# Step 8: Compute p-values
p_values = []
for i in range(len(waste_df)):
    original_stat = waste_df['local_stat'].iloc[i]
    if np.isnan(original_stat):
        p_values.append(np.nan)
        continue
    permuted_stats = [permuted_local_stats[perm][i] for perm in range(num_permutations) if not np.isnan(permuted_local_stats[perm][i])]
    if not permuted_stats:
        p_values.append(np.nan)
        continue
    if original_stat > 0:
        count = sum(1 for stat in permuted_stats if stat >= original_stat)
        p = (count + 1) / (len(permuted_stats) + 1)
    elif original_stat < 0:
        count = sum(1 for stat in permuted_stats if stat <= original_stat)
        p = (count + 1) / (len(permuted_stats) + 1)
    else:
        p = 0.5
    p_values.append(p)

# Step 9: Identify HH/LL
results = []
for index, row in waste_df.iterrows():
    borough = row['borough']
    local_stat = row['local_stat']
    p = p_values[index]
    if np.isnan(local_stat) or np.isnan(p):
        continue
    if local_stat > 0 and p < 0.05:
        if row['is_high']:
            results.append(f"{borough} (HH, statistical method={local_stat:.4f})")
        elif row['is_low']:
            results.append(f"{borough} (LL, statistical method={local_stat:.4f})")

# Final output
if results:
    print("FINAL ANSWER: " + ", ".join(results))
else:
    print("FINAL ANSWER: none")
